// Insert inserts the record into the database
func (t *ReservationEntry) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ReservationEntryTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Entry_no,
		t.Item_no,
		t.Location_code,
		t.Quantity,
		t.Reservation_status,
		t.Valid_to_date,
		t.Description,
		t.Creation_date,
		t.Transferred_from_entry_no,
		t.For_type,
		t.For_subtype,
		t.For_id,
		t.For_batch_name,
		t.For_prod_order_line,
		t.For_ref_no,
		t.From_type,
		t.From_subtype,
		t.From_id,
		t.From_batch_name,
		t.From_prod_order_line,
		t.From_ref_no,
		t.Expected_receipt_date,
		t.Shipment_date,
		t.Created_by,
		t.Cancelation_date,
		t.Canceled_or_changed_by,
		t.Variant_code,
		t.Serial_no,
		t.Lot_no,
		t.Bin_code,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (entry_no, item_no, location_code, quantity, reservation_status, valid_to_date, description, creation_date, transferred_from_entry_no, for_type, for_subtype, for_id, for_batch_name, for_prod_order_line, for_ref_no, from_type, from_subtype, from_id, from_batch_name, from_prod_order_line, from_ref_no, expected_receipt_date, shipment_date, created_by, cancelation_date, canceled_or_changed_by, variant_code, serial_no, lot_no, bin_code) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (entry_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Reservation_Entry: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ReservationEntryTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *ReservationEntry) InsertAll(records []*ReservationEntry, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Entry_no,
			r.Item_no,
			r.Location_code,
			r.Quantity,
			r.Reservation_status,
			r.Valid_to_date,
			r.Description,
			r.Creation_date,
			r.Transferred_from_entry_no,
			r.For_type,
			r.For_subtype,
			r.For_id,
			r.For_batch_name,
			r.For_prod_order_line,
			r.For_ref_no,
			r.From_type,
			r.From_subtype,
			r.From_id,
			r.From_batch_name,
			r.From_prod_order_line,
			r.From_ref_no,
			r.Expected_receipt_date,
			r.Shipment_date,
			r.Created_by,
			r.Cancelation_date,
			r.Canceled_or_changed_by,
			r.Variant_code,
			r.Serial_no,
			r.Lot_no,
			r.Bin_code,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ReservationEntryTableName)
	columns := []string{"entry_no", "item_no", "location_code", "quantity", "reservation_status", "valid_to_date", "description", "creation_date", "transferred_from_entry_no", "for_type", "for_subtype", "for_id", "for_batch_name", "for_prod_order_line", "for_ref_no", "from_type", "from_subtype", "from_id", "from_batch_name", "from_prod_order_line", "from_ref_no", "expected_receipt_date", "shipment_date", "created_by", "cancelation_date", "canceled_or_changed_by", "variant_code", "serial_no", "lot_no", "bin_code"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

